// Step 1: Get the data field as a string
const raw = $json.data;

// Step 2: Match the JSON part after "data:"
const match = raw.match(/data: (\[.*?\])\n?/);

if (!match) {
  return [{ json: { error: "Invalid data format" } }];
}

// Step 3: Parse the JSON array string
const dataArray = JSON.parse(match[1]);

// Step 4: Get the URL from the first object
const imageUrl = dataArray[0]?.url || null;

// Step 5: Return it
return [
  {
    json: {
      finalUrl: imageUrl
    }
  }
];
